#!/usr/bin/env bash
# MICA: writes the remaining schemas (labs, xray, report) + fixtures + extended contract tests.
# Run from the ROOT of the repo:   bash add_schemas_2.sh
# It OVERWRITES: schemas/src/mica_schemas/__init__.py, fixtures/README.md, tests/test_contract.py
# (they were generated by the previous script). New files: labs.py, xray.py, report.py, 3 fixtures.
set -euo pipefail
w() { mkdir -p "$(dirname "$1")"; cat > "$1"; echo "wrote: $1"; }

w schemas/src/mica_schemas/labs.py <<'MICA_EOF'
from typing import Literal, Optional

from pydantic import Field, model_validator

from ._base import MicaModel

Flag = Literal["low", "normal", "high", "unknown"]
RefSource = Literal["printed", "default", "none"]


class LabTest(MicaModel):
    name_raw: str                                   # exactly as read by OCR: "Hemoglobin"
    name_std: Optional[str] = None                  # standard name: "HGB"; None = not matched
    value: Optional[float] = None                   # None if it could not be read
    unit: Optional[str] = None
    ref_low: Optional[float] = None
    ref_high: Optional[float] = None
    flag: Flag = "unknown"
    ref_source: RefSource = "none"                  # printed on the report / default table / none
    ocr_confidence: Optional[float] = Field(default=None, ge=0, le=1)
    needs_review: bool = False                      # low confidence or unclear row
    bbox: Optional[list[float]] = None              # [x1, y1, x2, y2] in the source image

    @model_validator(mode="after")
    def _check(self):
        if self.bbox is not None and len(self.bbox) != 4:
            raise ValueError("bbox must be [x1, y1, x2, y2]")
        if self.ref_low is not None and self.ref_high is not None and self.ref_low > self.ref_high:
            raise ValueError("ref_low must be <= ref_high")
        has_ref = self.ref_low is not None or self.ref_high is not None
        if self.value is None or not has_ref:
            # no value or no range -> we do not guess a flag
            if self.flag != "unknown":
                raise ValueError("flag must be 'unknown' when value or reference range is missing")
            return self
        expected = "normal"
        if self.ref_low is not None and self.value < self.ref_low:
            expected = "low"
        elif self.ref_high is not None and self.value > self.ref_high:
            expected = "high"
        if self.flag != expected:
            raise ValueError(f"flag '{self.flag}' does not match value/range (expected '{expected}')")
        return self


class Labs(MicaModel):
    schema_version: str = "1.0"
    case_id: str
    source_file: str
    lab_name: Optional[str] = None
    report_date: Optional[str] = None
    tests: list[LabTest] = Field(default_factory=list)
    warnings: list[str] = Field(default_factory=list)   # e.g. "row 7 unit missing"
MICA_EOF

w schemas/src/mica_schemas/xray.py <<'MICA_EOF'
from typing import Literal, Optional

from pydantic import Field, model_validator

from ._base import MicaModel

DISCLAIMER_AR = "ملاحظة مساعدة آلية، مش تشخيص، ومحتاجة مراجعة أخصائي أشعة."

View = Literal["AP", "PA", "unknown"]
XrayLabel = Literal["normal", "pneumonia", "uncertain"]


class ModelInfo(MicaModel):
    name: str                                       # e.g. "densenet121-finetuned"
    version: str


class Prediction(MicaModel):
    label: XrayLabel                                # "uncertain" when probability is near 0.5
    probability: float = Field(ge=0, le=1)          # probability of the predicted class


class Xray(MicaModel):
    schema_version: str = "1.0"
    case_id: str
    image_file: str
    view: View = "unknown"
    model: ModelInfo
    prediction: Prediction
    probabilities: dict[str, float]                 # {"normal": 0.19, "pneumonia": 0.81}
    gradcam_file: Optional[str] = None
    disclaimer: str = DISCLAIMER_AR
    quality_warnings: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def _check(self):
        for k, v in self.probabilities.items():
            if not 0 <= v <= 1:
                raise ValueError(f"probability for '{k}' must be in [0, 1]")
        if self.probabilities and abs(sum(self.probabilities.values()) - 1.0) > 0.02:
            raise ValueError("probabilities must sum to 1 (+/- 0.02)")
        if not self.disclaimer.strip():
            raise ValueError("disclaimer cannot be empty")
        return self
MICA_EOF

w schemas/src/mica_schemas/report.py <<'MICA_EOF'
from typing import Literal, Optional

from pydantic import Field, model_validator

from ._base import MicaModel

NOT_MENTIONED_AR = "غير مذكور في الجلسة"

Status = Literal["draft", "reviewed", "signed"]
GeneratedBy = Literal["code", "llm"]


class Section(MicaModel):
    text: str
    # where the content came from, e.g. "seg:1", "extraction.chief_complaint", "labs", "xray"
    sources: list[str] = Field(default_factory=list)
    generated_by: GeneratedBy = "code"
    requires_review: bool = False

    @model_validator(mode="after")
    def _no_claim_without_source(self):
        if self.text.strip() != NOT_MENTIONED_AR and not self.sources:
            raise ValueError("a section with content must list its sources")
        if self.text.strip() == NOT_MENTIONED_AR and self.sources:
            raise ValueError("a 'not mentioned' section must have no sources")
        return self


class Sections(MicaModel):
    """The 7 fixed sections of the Arabic report."""

    chief_complaint: Section
    hpi: Section                                    # history of present illness
    past_history: Section                           # history, medications, allergies
    examination: Section
    investigations: Section                         # labs + x-ray
    assessment: Section
    plan: Section

    @model_validator(mode="after")
    def _assessment_needs_review(self):
        if not self.assessment.requires_review:
            raise ValueError("assessment must have requires_review=True")
        return self


class UnsupportedClaim(MicaModel):
    section: str
    text: str
    reason: str


class ReportMeta(MicaModel):
    model: Optional[str] = None
    prompt_version: Optional[str] = None


class Report(MicaModel):
    schema_version: str = "1.0"
    case_id: str
    language: str = "ar"
    status: Status = "draft"
    sections: Sections
    unsupported_claims: list[UnsupportedClaim] = Field(default_factory=list)
    meta: Optional[ReportMeta] = None
MICA_EOF

